{% test is_even(model, column_name) %}

with a as (
  select
    CAST({{ column_name }} AS BIGINT) as f
  from {{ model }}
),

b as (
  select
    f
  from a
  where MOD(f, 2) = 1
)

select *
from b

{% endtest %}

{% test relationships(model, column_name, field, to) %}
with p as (select {{ field }} as i from {{ to }}),
c as (select {{ column_name }} as i from {{ model }}),
x as (select c.i from (select i from c) c2 left join (select i from p) p2 on c2.i = p2.i where c2.i is not null and p2.i is null)
select * from x
{% endtest %}

{% test warn_if_odd(model, column_name) %}
  {{ config(severity = 'warn') }}

  select *
  from {{ model }}
  where not ((cast({{ column_name }} as integer) % 2) = 0)

{% endtest %}

{% test unique(model, column_name) %}
SELECT lower(trim({{ column_name }})) AS v,
       count(*) AS c
FROM {{ model }}
WHERE coalesce(is_deleted, false) = false
  AND {{ column_name }} IS NOT NULL
GROUP BY lower(trim({{ column_name }}))
HAVING count(*) > 1
{% endtest %}
